"""10. CPU-Bound Worker Threads: GIL (PYTHON_GIL=1) vs Free-Threaded (PYTHON_GIL=0)

Four OS threads execute pure-Python integer hashing/math and post digests to
`main`. Under PYTHON_GIL=1, threads take turns holding the GIL while siblings
stall in `waiting_gil`. Under PYTHON_GIL=0 (Python 3.14t), all 4 cores execute
Python bytecode simultaneously in true parallel!
"""

import queue
import threading

WORKERS = 4


def cpu_worker(wid: int, results: queue.Queue[str]) -> None:
    acc = wid & 0xFF
    for step in range(950):
        s_mask = step & 0xFF
        for j in range(3200):
            acc = (acc ^ (j & 0xFF) ^ s_mask) & 0xFF
        if step == 474 or step == 949:
            results.put(f"w{wid}:{acc:02x}")


def main() -> None:
    results: queue.Queue[str] = queue.Queue()
    threads = [
        threading.Thread(target=cpu_worker, args=(i, results), name=f"cpu_worker #{i}")
        for i in range(1, WORKERS + 1)
    ]
    for t in threads:
        t.start()

    for _ in range(WORKERS * 2):
        results.get()

    for t in threads:
        t.join()


if __name__ == "__main__":
    main()

"""05a. Waiting on I/O with GIL Threading

Even with the GIL enabled, waiting on network or disk I/O releases the GIL!
Ten threads overlap their `slow_io_task()` waits concurrently.
"""

import queue
import threading
import time

WORKERS = 10


def slow_io_task(idx: int) -> str:
    """Simulates waiting on a slow network/database response (releases GIL)."""
    time.sleep(0.045 + (idx % 3) * 0.012)
    return f"ok#{idx}"


def worker(idx: int, out: queue.Queue[str]) -> None:
    acc = sum(i * i for i in range(1500))
    status = slow_io_task(idx)
    out.put(f"{status}:{acc % 97}")


def main() -> None:
    out: queue.Queue[str] = queue.Queue()
    threads = [
        threading.Thread(target=worker, args=(i, out), name=f"io_thread #{i}")
        for i in range(1, WORKERS + 1)
    ]
    for t in threads:
        t.start()
    for _ in range(WORKERS):
        out.get()
    for t in threads:
        t.join()


if __name__ == "__main__":
    main()

"""12. Free-Threaded Lock Contention (PYTHON_GIL=0 + threading.Lock)

Removing the GIL unlocks multi-core Python, but shared mutable state still
requires synchronization! Here 4 free-threaded workers run parallel CPU bursts
and then contend on `ledger_lock`, revealing Amdahl's Law & lock handoff arrows.
"""

import queue
import threading

WORKERS = 4


def account_worker(
    wid: int, ledger_lock: threading.Lock, ledger: list[int], done_q: queue.Queue[str]
) -> None:
    for step in range(3):
        # Parallel lock-free local computation on separate CPU cores
        acc = 0
        for i in range(240):
            im = i & 0xFF
            for j in range(1800):
                acc = (acc ^ (j & 0xFF) ^ im ^ wid) & 0xFF

        # Serialized critical section protected by explicit Lock
        with ledger_lock:
            crit = 0
            for j in range(180_000):
                crit = (crit ^ (j & 0xFF)) & 0xFF
            ledger.append(acc ^ crit)

    done_q.put(f"w{wid}:ok")


def main() -> None:
    ledger_lock = threading.Lock()
    ledger: list[int] = []
    done_q: queue.Queue[str] = queue.Queue()

    threads = [
        threading.Thread(
            target=account_worker,
            args=(i, ledger_lock, ledger, done_q),
            name=f"worker #{i}",
        )
        for i in range(1, WORKERS + 1)
    ]
    for t in threads:
        t.start()
    for _ in range(WORKERS):
        done_q.get()
    for t in threads:
        t.join()
    assert len(ledger) == WORKERS * 3


if __name__ == "__main__":
    main()
